from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _units(ratio: Fraction, method: str) -> int:
    """`ratio` rounded to a whole number by `method`."""
    negative = ratio < 0
    magnitude = -ratio if negative else ratio
    floor = magnitude.numerator // magnitude.denominator
    rest = magnitude - floor
    if method == DOWN or rest < Fraction(1, 2):
        count = floor
    elif rest > Fraction(1, 2):
        count = floor + 1
    elif method == HALF_UP:
        count = floor + 1
    else:
        count = floor + (floor % 2)
    return -count if negative else count


def _build(count: int, negative: bool, step: Decimal) -> Decimal:
    """`count` multiples of `step`, with the exponent of `step`."""
    sign, digits, exponent = step.as_tuple()
    coefficient = int("".join(map(str, digits))) * abs(count)
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(coefficient)), exponent))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    count = _units(Fraction(value) / Fraction(step), method)
    return _build(count, value.is_signed(), step)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    for amount in amounts:
        _check(amount, step, HALF_UP)
    if not amounts:
        _check(Decimal(0), step, HALF_UP)
        return []
    ratios = [Fraction(a) / Fraction(step) for a in amounts]
    counts = [_units(r, DOWN) for r in ratios]
    negatives = [a.is_signed() for a in amounts]
    whole = _units(sum(ratios, Fraction(0)), HALF_UP)
    rest = whole - sum(counts)
    for i in range(len(counts) - 1, -1, -1):
        if amounts[i] != 0:
            counts[i] += rest
            negatives[i] = counts[i] < 0
            break
    return [_build(c, n, step) for c, n in zip(counts, negatives)]


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(value, Decimal):
        step = Decimal((0, (1,), -places))
        return format(round_amount(value, step, method), "f")
    if method != HALF_EVEN:
        raise ValueError("a float is only written half to even")
    return format(value, f".{places}f")
