"""The rounding rules in meterbill.money."""

import unittest
from decimal import Decimal

from meterbill import money
from meterbill.money import CENT, DOWN, HALF_EVEN, HALF_UP


def D(text: str) -> Decimal:
    return Decimal(text)


class RoundAmount(unittest.TestCase):
    def test_ties(self):
        self.assertEqual(money.round_amount(D("0.125"), CENT, HALF_UP), D("0.13"))
        self.assertEqual(money.round_amount(D("0.125"), CENT, HALF_EVEN), D("0.12"))
        self.assertEqual(money.round_amount(D("-0.125"), CENT, HALF_UP), D("-0.13"))
        self.assertEqual(money.round_amount(D("0.129"), CENT, DOWN), D("0.12"))

    def test_exponent_of_step(self):
        self.assertEqual(str(money.round_amount(D("7"), D("0.05"), HALF_UP)), "7.00")
        self.assertEqual(str(money.round_amount(D("7.5"), D("1"), HALF_EVEN)), "8")
        self.assertEqual(str(money.round_amount(D("0.37"), D("0.10"), HALF_UP)), "0.40")

    def test_errors(self):
        with self.assertRaises(TypeError):
            money.round_amount(1.5, CENT, HALF_UP)
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), CENT, "up")
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), D("0"), HALF_UP)

    def test_large_value(self):
        big = D("1" + "0" * 40 + ".005")
        self.assertEqual(money.round_amount(big, CENT, HALF_UP), D("1" + "0" * 40 + ".01"))


class Allocate(unittest.TestCase):
    def test_parts_add_up(self):
        amounts = [D("0.335"), D("0.335"), D("0.335")]
        parts = money.allocate(amounts, CENT)
        self.assertEqual(sum(parts), money.round_amount(sum(amounts), CENT, HALF_UP))
        self.assertEqual(parts, [D("0.33"), D("0.33"), D("0.35")])

    def test_empty(self):
        self.assertEqual(money.allocate([], CENT), [])


class Legacy(unittest.TestCase):
    def test_settle(self):
        self.assertEqual(money.legacy_cents(2.675), 2.68)
        self.assertEqual(money.legacy_cents(-4.25), -4.25)
        self.assertEqual(money.legacy_cents(1.2345, 3), 1.235)


class Fixed(unittest.TestCase):
    def test_float(self):
        self.assertEqual(money.fixed(2.675, 2), "2.67")
        self.assertEqual(money.fixed(2.5, 0), "2")
        with self.assertRaises(ValueError):
            money.fixed(2.5, 0, HALF_UP)

    def test_decimal(self):
        self.assertEqual(money.fixed(D("2.675"), 2, HALF_UP), "2.68")
        self.assertEqual(money.fixed(D("2.5"), 0), "2")
        self.assertEqual(money.fixed(D("1E+3"), 1), "1000.0")
        self.assertEqual(money.fixed(D("0.00001"), 4, HALF_UP), "0.0000")


if __name__ == "__main__":
    unittest.main()
